import { Command } from "commander";
export declare const TILTFILE_RELATIVE_PATH = ".tdk/.tdk-out/Tiltfile";
export declare const TILT_UP_COMMAND = "tilt up -f .tdk/.tdk-out/Tiltfile -- --focus=<stack>";
export declare const EJECTED_CONTENT = "# Ejected from TDK\n\n`tdk eject` wrote this file and nothing else. It did not copy, move or generate anything, and it did\nnot remove TDK. What exists is what TDK had already generated, and that is still TDK-owned output.\n\n## Where the generated files are\n\n- `.tdk/.tdk-out/` holds the Tiltfile and the engine it loads (`tdk-cli-ext/`). It is git-ignored.\n  `tdk config regenerate` rewrites the master files in it.\n- The per-service Compose files (`services/<stack>/<name>/.autogenerated/`), the golden-layer\n  Dockerfile and the Traefik file (`.tdk/.tdk-out/`) are written by Tilt when it runs, not by\n  `tdk eject`. Until Tilt has run they do not exist. They are git-ignored too.\n- Your own Dockerfiles, `service.json` files and source code are untouched.\n\n## Running the stack without the tdk CLI\n\nThere is no Tiltfile at the project root, so a plain `tilt up` does not find one. TDK runs:\n\n    tilt up -f .tdk/.tdk-out/Tiltfile -- --focus=<stack>\n\nfrom the project root (`<stack>` is a stack name under `services/`; without `--focus` the Tiltfile\nfalls back to its default phase). The Tiltfile still reads `.tdk/project.json` and the\n`service.json` files, so those must stay. `tdk up` also does steps before Tilt starts (it chooses\nhost ports and exports them to Tilt); running Tilt by hand skips them.\n\n## Cleaning up\n\nOptional to delete later: this file, and `.tdk/` plus the `service.json` files if you stop using TDK.\nDeleting them also removes what the Tiltfile needs.\n\nTo go back to TDK: install it and run `tdk config regenerate`.\n";
export declare const ejectCommand: Command;
